import 'package:flutter/material.dart';import '../data/income_database.dart';import '../models/income_models.dart';import 'income_editor.dart';
class HistoryPage extends StatefulWidget{const HistoryPage({super.key,required this.revision,required this.onChanged});final int revision;final VoidCallback onChanged;@override State<HistoryPage> createState()=>_HistoryPageState();}
class _HistoryPageState extends State<HistoryPage>{String query='';IncomeType? filter;@override Widget build(BuildContext context)=>FutureBuilder<List<IncomeRecord>>(key:ValueKey(widget.revision),future:IncomeDatabase.instance.all(),builder:(context,snapshot){var records=snapshot.data??const<IncomeRecord>[];records=records.where((r){final t=(r.type.label+' '+(r.source??'')+' '+(r.account??'')+' '+(r.memo??'')).toLowerCase();return(filter==null||r.type==filter)&&t.contains(query.toLowerCase());}).toList();return Column(children:[Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Type, Source, Account 검색'),onChanged:(v)=>setState(()=>query=v)),const SizedBox(height:8),DropdownButtonFormField<IncomeType?>(initialValue:filter,decoration:const InputDecoration(labelText:'Type 필터'),items:[const DropdownMenuItem(value:null,child:Text('전체')),...IncomeType.values.map((e)=>DropdownMenuItem(value:e,child:Text(e.label)))],onChanged:(v)=>setState(()=>filter=v))])),Expanded(child:records.isEmpty?const Center(child:Text('수입 기록이 없습니다.')):ListView.builder(itemCount:records.length,itemBuilder:(context,i){final r=records[i];final accountText=r.account==null?'':' · '+r.account!;return ListTile(title:Text((r.source??r.type.label)+' · '+r.type.label),subtitle:Text(r.date.year.toString()+'.'+r.date.month.toString()+'.'+r.date.day.toString()+accountText),trailing:Text('₩'+r.amount.toString()),onTap:() async {final changed=await Navigator.push<bool>(context,MaterialPageRoute(builder:(_)=>IncomeEditor(record:r)));if(changed==true){widget.onChanged();setState((){});}},onLongPress:() async {final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('기록 삭제'),content:const Text('이 수입 기록을 삭제할까요?'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('취소')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('삭제'))]));if(ok==true&&r.id!=null){await IncomeDatabase.instance.delete(r.id!);widget.onChanged();setState((){});}});}))]);});}
